int run_test_case(const char *scenario_name,
                    const char *base_url,
                    const char *query_to_set,
                    unsigned int flags,
                    const char *expected_url)
{
  CURLU *u = curl_url();
  CURLUcode rc;
  char *result_url = NULL;
