    printf("  behavior did not match our analysis (it was %d failures).\n", failures);
    printf("  Check the 'Actual URL' vs 'Expected URL' above.\n");
    printf("  The logic may have been fixed in this version of libcurl.\n\n");
  }

  return 0;
}
