## nego_server.py
```python
#!/usr/bin/env python3
"""
Test server speaking the curl stub GSS protocol.

Stub protocol (lib/curl_gssapi.c):
- Client sends base64(creds:target:type:padding)
- Server responds with:
  - base64("C") = Qw== for Continue
  - base64("D") = RA== for Done (auth complete)

For KRB5: client sends type=1 (STUB_GSS_KRB5), server replies D -> GSS_S_COMPLETE
This causes curl to set http_negotiate_state = GSS_AUTHSUCC

The server tracks authenticated connections by TCP socket and serves
subsequent requests using the original identity (persistent Negotiate auth,
like Windows IIS with Kerberos).
"""
import http.server
import socketserver
import base64
import json
import sys

conn_auth = {}  # conn_key -> identity
request_log = []


class NegotiateHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def _key(self):
        return f"{self.client_address[0]}:{self.client_address[1]}"

    def do_GET(self):
        k = self._key()
        auth = self.headers.get("Authorization", "")

        if auth.startswith("Negotiate "):
            token_b64 = auth.split(" ", 1)[1]
            try:
                token = base64.b64decode(token_b64)
                # Token format: creds:HTTP@host:type:padding
                parts = token.split(b":")
                identity = parts[0].decode("utf-8", errors="replace")
            except Exception as e:
                identity = f"DECODE_ERR:{e}"

            conn_auth[k] = identity

            # Reply with "D" (Done) base64-encoded to complete the handshake
            # This tells curl's stub GSS that auth is complete -> GSS_S_COMPLETE
            # -> http_negotiate_state = GSS_AUTHSUCC
            done_token = base64.b64encode(b"D").decode()

            self.send_response(200)
            self.send_header("WWW-Authenticate", f"Negotiate {done_token}")
            self.send_header("Content-Type", "application/json")
            body = json.dumps({
                "status": "authenticated",
                "identity": identity,
                "conn": k,
                "mechanism": "negotiate_complete"
            })
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body.encode())

            print(f"[AUTH] conn={k} identity={identity} -> GSS_AUTHSUCC", flush=True)

        elif k in conn_auth:
            # PERSISTENT AUTH: connection already authenticated
            # No Authorization header needed — identity comes from TCP conn
            identity = conn_auth[k]

            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            body = json.dumps({
                "status": "persistent_auth",
                "identity": identity,
                "conn": k,
                "auth_header": auth[:80] if auth else "(none)",
                "note": "Identity from TCP connection, NOT from current request"
            })
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body.encode())

            print(f"[PERSISTENT] conn={k} identity={identity} "
                  f"auth_hdr={'YES' if auth else 'NO'}", flush=True)

        else:
            # 401 challenge
            self.send_response(401)
            self.send_header("WWW-Authenticate", "Negotiate")
            self.send_header("Content-Type", "text/plain")
            body = "Authentication required"
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body.encode())

            print(f"[401] conn={k} no auth", flush=True)


class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8999
    s = Server(("127.0.0.1", port), NegotiateHandler)
    print(f"[*] Negotiate stub server on :{port}", flush=True)
    s.serve_forever()
```
